import{_ as t,o as a,c as i,ae as s}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"UX Design","description":"","frontmatter":{},"headers":[],"relativePath":"design/ux-design.md","filePath":"design/ux-design.md"}'),r={name:"design/ux-design.md"};function l(n,e,o,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="ux-design" tabindex="-1">UX Design <a class="header-anchor" href="#ux-design" aria-label="Permalink to &quot;UX Design&quot;">​</a></h1><blockquote><p>Canonical design document consolidated from <code>docs/design/ux-design.md</code> during Stage 22. Stage 23 will reconcile detailed source anchors where needed.</p></blockquote><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Saivage v3 is a dense control room for supervising an autonomous runtime, not a marketing-style app. The UI provides a left navigation rail, live dashboard, chat command stream, card tree/plan view, agent conversation inspector, file browser, and debug console. The card tree is the primary navigation model.</p><p>The core UX principle is: <strong>every important runtime fact is inspectable from a card</strong>. Cards link to their plan diary, review results, processes, logs, artifacts, notes, and related cards.</p><p>The authoritative schemas and filesystem layout are defined in <code>data-model.md</code>.</p><hr><h2 id="ux-goals" tabindex="-1">UX Goals <a class="header-anchor" href="#ux-goals" aria-label="Permalink to &quot;UX Goals&quot;">​</a></h2><ul><li>Make the current runtime state obvious: running card, current agent, queued work, failures, blocked work, and global pause state.</li><li>Let users talk to the analyst without losing operational context.</li><li>Make the card tree the primary navigation model.</li><li>Provide rich inspection tools: agent conversations, file browser, debug state, errors, timeline, and artifacts view.</li><li>Support safe intervention: pause globally, abort/restart goals, kill processes, add directives, inspect outputs.</li><li>Keep attachments rendered in the web UI only; Telegram links to cards or notifies that attachments exist.</li><li>Avoid hidden system state: plan cards are visible in the tree.</li></ul><hr><h2 id="application-shell" tabindex="-1">Application Shell <a class="header-anchor" href="#application-shell" aria-label="Permalink to &quot;Application Shell&quot;">​</a></h2><p>The application shell follows a standard operational-console pattern:</p><ul><li><strong>Left rail</strong>: primary sections with icon + label + hotkey.</li><li><strong>Workspace header</strong>: current section title, project path/name, live status chip, global pause chip if paused.</li><li><strong>Main workspace</strong>: tab-specific view.</li><li><strong>Keyboard shortcuts</strong>: numeric section shortcuts and <code>/</code> to focus chat.</li><li><strong>API token handling</strong>: local token entry for secured deployments.</li></ul><p>Recommended navigation:</p><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th></tr></thead><tbody><tr><td>Dashboard</td><td>Live command room: analyst chat plus runtime summary.</td></tr><tr><td>Cards</td><td>Recursive card tree, board, detail, diary, review, process views.</td></tr><tr><td>Agents</td><td>Planner/executor/reviewer/analyst conversations and tool traces.</td></tr><tr><td>Files</td><td>Browse <code>.saivage/</code> metadata and <code>.saivage-work/</code> outputs safely.</td></tr><tr><td>Debug</td><td>Runtime state, errors, timeline, raw JSON, health diagnostics.</td></tr><tr><td>Docs</td><td>Open generated docs/reference.</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Rail[Left Rail] --&gt; Dash[Dashboard]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Rail --&gt; Cards[Cards]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Rail --&gt; Agents[Agents]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Rail --&gt; Files[Files]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Rail --&gt; Debug[Debug]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Dash --&gt; Chat[Analyst Chat]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Dash --&gt; Status[Runtime Status]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cards --&gt; Tree[Card Tree]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cards --&gt; Detail[Card Detail]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Agents --&gt; Conversations[Agent Conversations]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Files --&gt; Browser[Metadata / Output Browser]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Debug --&gt; Diagnostics[State / Errors / Timeline]</span></span></code></pre></div><hr><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>The dashboard is the default control room, combining the analyst chat stream and the runtime status panel.</p><h3 id="analyst-chat" tabindex="-1">Analyst Chat <a class="header-anchor" href="#analyst-chat" aria-label="Permalink to &quot;Analyst Chat&quot;">​</a></h3><p>The analyst chat is a persistent command stream.</p><ul><li>WebSocket connection with visible state: connected, connecting, offline, unauthorized.</li><li>API token entry for secured deployments.</li><li>Chat history stored in agent session records, recoverable on reload.</li><li>Markdown rendering of analyst responses.</li><li>System/event messages inline in the stream.</li><li>Send on Enter, multiline with Shift+Enter, <code>/</code> focuses input.</li><li>Scroll-to-latest affordance when new messages arrive offscreen.</li></ul><p>Analyst capabilities shown in chat:</p><ul><li>Create/edit/move/delete cards at any level.</li><li>Add notes/directives to cards.</li><li>Inspect cards, plan diary, review results, process outputs, artifacts, active agents, and runtime state.</li><li>Control runtime: global pause/resume, abort/restart goal, restart task card, kill process.</li></ul><p>Chat should include structured action previews before destructive actions, for example aborting a goal or killing a process.</p><h3 id="runtime-status-panel" tabindex="-1">Runtime Status Panel <a class="header-anchor" href="#runtime-status-panel" aria-label="Permalink to &quot;Runtime Status Panel&quot;">​</a></h3><p>The runtime status panel is card-aware.</p><p>Metrics:</p><ul><li>Runtime status: running, idle, paused, error, unauthorized.</li><li>Current active card.</li><li>Running process count.</li><li>Queued ready tasks.</li><li>Done goals.</li><li>Failed/blocked cards.</li><li>Active agent count, excluding analyst.</li></ul><p>Sections:</p><ul><li><strong>Current Work</strong>: active card title, type, parent goal, elapsed time.</li><li><strong>Workers</strong>: planner/executor/reviewer currently active, if any.</li><li><strong>Queue</strong>: next ready cards in priority order.</li><li><strong>Recent History</strong>: recent completed goals/tasks, failures, reviewer results, escalations.</li></ul><hr><h2 id="cards-section" tabindex="-1">Cards Section <a class="header-anchor" href="#cards-section" aria-label="Permalink to &quot;Cards Section&quot;">​</a></h2><p>The Cards section is the primary workspace. It supports four presentations over the same card model:</p><ul><li><strong>Tree</strong>: recursive project -&gt; goal -&gt; plan -&gt; sub-goals/tasks.</li><li><strong>Board</strong>: status columns (<code>drafting</code>, <code>backlog</code>, <code>active</code>, <code>running</code>, <code>blocked</code>, <code>done</code>, <code>failed</code>, <code>cancelled</code>).</li><li><strong>Leaderboard</strong>: query over done result cards sorted by a selected metric.</li><li><strong>Timeline</strong>: duration-focused view for cards/processes.</li></ul><h3 id="tree-view" tabindex="-1">Tree View <a class="header-anchor" href="#tree-view" aria-label="Permalink to &quot;Tree View&quot;">​</a></h3><p>Tree requirements:</p><ul><li>Project card is root.</li><li>Plan cards are visible.</li><li>Maximum goal depth is configurable, default 5 levels.</li><li>Use type icons for goal, plan, architecture, code, test, doc, data, research, ops.</li><li>Show status, priority, blocked/dependency markers, active agent, and unread notes/review markers.</li><li>Support focus by card ID from dashboard, agents, files, debug, and Telegram links.</li></ul><p>Tree actions:</p><ul><li>Create child card.</li><li>Edit card while not scheduled.</li><li>Add note/directive.</li><li>Move/reparent valid cards.</li><li>Abort goal.</li><li>Restart task/goal.</li><li>Open plan diary.</li><li>Open related process output.</li><li>Open artifacts/attachments.</li></ul><h3 id="card-detail" tabindex="-1">Card Detail <a class="header-anchor" href="#card-detail" aria-label="Permalink to &quot;Card Detail&quot;">​</a></h3><p>Card detail is the central inspection surface.</p><p>Sections:</p><ul><li>Header: title, type, status, parent, priority, urgency, created by, updated time.</li><li>Description and acceptance criteria.</li><li>Dependencies and blocked-by/blocks graph.</li><li>Notes/activity log with mutable-until-handled behavior.</li><li>Results and metrics.</li><li>Artifacts and attachments. Attachments render inline in the web UI.</li><li>Process list: async commands launched for this card, state, elapsed, tail output, kill/wait controls.</li><li>Related agent conversation links.</li></ul><p>Goal cards additionally show:</p><ul><li>Child card summary.</li><li>Plan card link.</li><li>Latest reviewer assessment.</li><li>Goal completion gate: reviewer pass required.</li></ul><p>Plan cards additionally show:</p><ul><li>Planner diary rendered from structured JSON as Markdown.</li><li>Planner invocations: initial, all tasks complete, review rejection, failure.</li><li>Card mutations requested by planner.</li><li>Reviewer assessments appended to the diary.</li></ul><p>Terminal task cards additionally show:</p><ul><li>Executor result.</li><li>Process output files and tails.</li><li>Artifacts generated by the task.</li><li>Skill file loaded/linked for the card type.</li></ul><h3 id="board-view" tabindex="-1">Board View <a class="header-anchor" href="#board-view" aria-label="Permalink to &quot;Board View&quot;">​</a></h3><p>The board is a compact operational view for scanning state. Cards are grouped by status. It should support filtering by type, parent goal, tag, priority, and text search.</p><h3 id="leaderboard-view" tabindex="-1">Leaderboard View <a class="header-anchor" href="#leaderboard-view" aria-label="Permalink to &quot;Leaderboard View&quot;">​</a></h3><p>The leaderboard is a saved query over done result cards. It is not a separate data model. Rows link to card detail and expose the same artifacts, metrics, process logs, and review history.</p><h3 id="timeline-view" tabindex="-1">Timeline View <a class="header-anchor" href="#timeline-view" aria-label="Permalink to &quot;Timeline View&quot;">​</a></h3><p>Timeline combines card duration and process duration:</p><ul><li>Card started/completed times.</li><li>Process start/end and still-running markers.</li><li>Review and planner invocation markers.</li><li>Global pause intervals.</li></ul><hr><h2 id="agents-section" tabindex="-1">Agents Section <a class="header-anchor" href="#agents-section" aria-label="Permalink to &quot;Agents Section&quot;">​</a></h2><p>The Agents section shows all active and historical agent conversations scoped to their roles.</p><p>Agent list:</p><ul><li>Analyst conversations (chat sessions).</li><li>Planner for active goal.</li><li>Executor for active goal.</li><li>Reviewer when active.</li><li>Content supervisor events when it blocks or quarantines content.</li></ul><p>Conversation detail:</p><ul><li>Messages grouped into reasoning/tool-call/tool-result steps.</li><li>Tool calls expandable by default for current work, collapsed for old history.</li><li>Model/provider metadata.</li><li>Runtime events, model repair/recovery events, tool errors.</li><li>Links from tool calls to affected cards, processes, files, artifacts, and quarantined content.</li></ul><p>The analyst is always available concurrently with the runtime. Other agents do not run in parallel by default.</p><hr><h2 id="files-section" tabindex="-1">Files Section <a class="header-anchor" href="#files-section" aria-label="Permalink to &quot;Files Section&quot;">​</a></h2><p>The Files section separates persistent state from generated outputs.</p><p>Panels:</p><ul><li>Metadata browser (<code>.saivage/</code>).</li><li>Work/output browser (<code>.saivage-work/</code>).</li><li>Notes queue / directives.</li><li>Quarantine browser for content-supervisor blocks.</li></ul><p>Behaviors:</p><ul><li>Breadcrumb navigation.</li><li>Directory stats.</li><li>JSON highlighting.</li><li>Markdown rendering where appropriate.</li><li>Safe file reads through MCP; dangerous/external provenance is routed through content supervision.</li><li>Downloaded files must enter through <code>download_file</code>, not arbitrary writes.</li></ul><hr><h2 id="debug-section" tabindex="-1">Debug Section <a class="header-anchor" href="#debug-section" aria-label="Permalink to &quot;Debug Section&quot;">​</a></h2><p>The Debug section exposes raw runtime internals:</p><ul><li><strong>State</strong>: runtime state, card index, active agents, process registry, global pause state, configuration.</li><li><strong>Errors</strong>: source, type, severity, message, details, timestamp.</li><li><strong>Timeline</strong>: runtime events, card transitions, process events, planner/reviewer invocations, content-supervisor events.</li></ul><p>Debug is for inspection, not normal operation. Actions should link back to the relevant card or process instead of duplicating controls.</p><hr><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><ul><li>Notify when goals are done.</li><li>Depth-0 planner escalation must notify via Telegram and be visible in the web UI.</li><li>Telegram notifications should link to the relevant card. Attachments are not rendered in Telegram; Telegram can say attachments exist.</li></ul><hr><h2 id="ux-coverage-checklist" tabindex="-1">UX Coverage Checklist <a class="header-anchor" href="#ux-coverage-checklist" aria-label="Permalink to &quot;UX Coverage Checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>UX location</th></tr></thead><tbody><tr><td>Analyst chat</td><td>Dashboard</td></tr><tr><td>Global pause/resume</td><td>Dashboard status + analyst command</td></tr><tr><td>Abort/restart goal</td><td>Card detail actions + analyst command</td></tr><tr><td>Restart task</td><td>Terminal card detail actions</td></tr><tr><td>Kill/wait/tail process</td><td>Card detail process panel</td></tr><tr><td>Card tree</td><td>Cards / Tree</td></tr><tr><td>Plan diary</td><td>Visible plan card detail</td></tr><tr><td>Reviewer assessment</td><td>Plan card diary + goal detail summary</td></tr><tr><td>Attachments</td><td>Card detail, web only</td></tr><tr><td>Artifacts/files</td><td>Files section + card detail links</td></tr><tr><td>Agent conversations</td><td>Agents section</td></tr><tr><td>Content supervision/quarantine</td><td>Files + Debug + card notes</td></tr><tr><td>Depth-0 escalation</td><td>Telegram notification + UI banner/card marker</td></tr><tr><td>Debug state/errors/timeline</td><td>Debug section</td></tr></tbody></table>`,83)])])}const g=t(r,[["render",l]]);export{h as __pageData,g as default};
